"""Generate the corporate pages, sharing the existing site design and demo."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parents[1]
PUBLIC = ROOT / 'public'
BASE = 'https://rainc.tech'
DATE = '2026-10-12'
ART = (ROOT / 'site/partials/hero-art.html').read_text()
